    correctKey: 'A',
    explanation: '湿り空気の比エンタルピーh = 1.006t + x(2501 + 1.86t)[kJ/kg(DA)]。1.006[kJ/(kg·K)]：乾き空気の定圧比熱、2501[kJ/kg]：0℃での水の蒸発潜熱、1.86[kJ/(kg·K)]：水蒸気の定圧比熱。h＝1.006t＋x(2501＋1.86t)の第1項は乾き空気1kgの顕熱、第2項は含まれる水蒸気がもつ熱である。2501kJ/kgは0℃における水の蒸発潜熱、1.86kJ/(kg·K)は水蒸気の定圧比熱、1.006kJ/(kg·K)は乾き空気の定圧比熱を表す。全熱負荷は質量流量と入口・出口のエンタルピー差の積で求められる。\n\n【図解】比エンタルピー式の各項\n　項｜係数｜意味\n　乾き空気の顕熱｜1.006 kJ/(kg·K)｜乾き空気の定圧比熱\n　水の蒸発潜熱｜2501 kJ/kg｜0℃を基準とする\n　水蒸気の顕熱｜1.86 kJ/(kg·K)｜水蒸気の定圧比熱\n　⇒ 全熱負荷＝質量流量×エンタルピー差で計算できる\n　⚠ 2501と1.86を入れ替えない。基準は0℃の乾き空気1kgあたりである。',
