    explanation: 'ペアガラスの断熱性向上の主因は2枚ガラス間の静止空気層（6〜16mm）の熱抵抗。空気のλ≒0.024W/(m·K)は非常に小さく大きな断熱効果をもたらす。Low-eコーティング追加で放射伝熱も抑制できる。複層ガラスの断熱性能は主に中空層の熱抵抗によるもので、乾燥空気層はおおむね12mm程度で効果が頭打ちとなり、それ以上厚くすると中空層内で対流が生じて改善しない。さらに性能を高めるにはアルゴンガス封入やLow-E膜の付加が有効である。日射遮蔽を主目的とする場合、Low-E膜は屋外側ガラスの中空層側に設ける。\n\n【図解】ガラス仕様と熱貫流率\n　仕様｜U値の目安｜断熱の要因\n　単板ガラス6mm｜約6.0 W/(m²·K)｜ほぼガラスの表面抵抗のみ\n　複層ガラス（空気層12mm）｜約3.0 W/(m²·K)｜中空層の熱抵抗\n　Low-E複層ガラス｜1.5〜2.0 W/(m²·K)｜放射伝熱の抑制\n　⇒ 断熱の主因は中空層の熱抵抗と低放射膜による放射低減\n　⚠ 中空層は厚いほど良いのではない。12mm程度を超えると対流により効果が頭打ちになる。',
