    correctKey: 'D',
    explanation: '潜熱蓄熱材（PCM: Phase Change Material）は融点付近の相変化に伴う大きな潜熱（融解熱）を利用して温度変動を抑制しながら大量の熱を蓄える。建材に混入すると室温変動抑制・ピーク負荷低減に効果がある。PCMは融解・凝固に伴う潜熱を利用する蓄熱材で、相変化温度付近では温度がほとんど変わらないまま大量の熱を出し入れできる。パラフィン系や水和塩系があり、内装材や天井材に組み込んで室温変動の抑制やピークシフトに用いる。顕熱蓄熱に比べ、同じ蓄熱量をはるかに小さい体積で実現できる点が特徴である。\n\n【図解】蓄熱方式の比較\n　方式｜蓄熱の原理｜特徴\n　顕熱蓄熱（水・躯体）｜温度上昇により蓄熱｜安価だが体積が大きい\n　潜熱蓄熱（PCM・氷）｜相変化に伴う潜熱｜小容積で大きな蓄熱量\n　化学蓄熱｜可逆的な化学反応｜高密度だが実用例は限定的\n　⇒ PCMは相変化温度付近で室温をほぼ一定に保つ\n　⚠ 相変化温度が室温域から外れると効果がない。融点の選定が設計の要点である。',
