    explanation: '換気量を増やすと新鮮空気量が増え空気質が向上するが、外気の熱処理（冷却・加熱・除加湿）エネルギーと搬送動力が増大する。必要最小限の換気量を適切に設定し、熱回収換気（全熱交換器）と組み合わせることが省エネ上重要。換気量を増やせば室内空気質は改善するが、外気を冷却・加熱・除湿・加湿するエネルギーは増加する。そこでCO₂濃度に応じて必要量だけ導入する外気量制御や、全熱交換器による熱回収が用いられる。一方で中間期など外気条件が良いときは、外気冷房として外気を積極的に取り入れるほうが省エネになる。\n\n【図解】外気量とエネルギーの関係\n　状況｜外気量の考え方｜理由\n　在室者が少ない｜CO₂制御で絞る｜過剰な外気負荷を避ける\n　中間期・低外気温時｜外気冷房で増やす｜冷凍機を停止できる\n　厳寒期・猛暑期｜最小限＋熱回収｜外気負荷が大きい\n　⇒ 外気量は空気質とエネルギーの両面から最適点を探る\n　⚠ 換気量を増やせば必ず省エネになるとは限らない。外気条件により向きが逆転する。',
