    explanation: '暖房COP = 加熱量/消費電力 = (冷却量+消費電力)/消費電力 = 冷房COP + 1。このため暖房COPは冷房COPより約1大きく一般的に高い。例：冷房COP=3なら暖房COP≒4となる。これがヒートポンプ暖房の省エネ優位性の根拠。暖房COPは加熱量を消費電力で除した値であり、加熱量は冷却量に圧縮動力が加わったものとなるため、理論上は冷房COPより1程度大きくなる。実際の省エネ性能の評価には、部分負荷や季節変動を織り込んだAPF（通年エネルギー消費効率）やIPLVが用いられる。COPは外気温や水温で大きく変動する。\n\n【図解】効率指標の違い\n　指標｜内容｜特徴\n　冷房COP｜冷却量÷消費電力｜定格条件での値\n　暖房COP｜加熱量÷消費電力｜冷房COPより1程度大きい\n　APF｜期間全体での効率｜部分負荷特性を反映\n　⇒ 暖房では圧縮仕事も熱として利用されるためCOPが大きくなる\n　⚠ COPは定格条件の値にすぎない。実運転の評価にはAPFなど期間効率を用いる。',
