    explanation: '開放型冷却塔は冷却水を外気と直接接触させて水の蒸発潜熱で冷却する。蒸発水分補給（補給水）・濃縮管理（ブロー）・レジオネラ菌対策（消毒・清掃）が必要。理論限界出口水温は外気湿球温度（ドライブには届かない）となる。開放型冷却塔は冷却水を大気に直接接触させ、一部を蒸発させたときの潜熱で残りの水を冷却する。空気と接触するため塵埃の混入や濃縮による水質悪化が生じ、レジオネラ属菌対策として建築物衛生法に基づく年1回以上の清掃や、水質管理・薬注が必要になる。出口水温は外気湿球温度より下げられない。\n\n【図解】冷却塔の型式と管理\n　型式｜冷却の方法｜特徴\n　開放型｜冷却水を直接大気に接触させる｜効率は高いが水質管理が必要\n　密閉型｜熱交換器を散水と通風で冷却｜水質は良好だが大型・高価\n　共通事項｜外気湿球温度が下限｜出口水温は湿球温度＋3〜5℃\n　⇒ 冷却塔の性能は乾球温度ではなく湿球温度で決まる\n　⚠ 冷却塔は外気取入口から離して配置する。飛散水によるレジオネラ拡散を防ぐため。',
