    correctKey: 'B',
    explanation: '相当外気温度（SAT）は、壁面が受ける日射の影響を外気温度に加算して表した仮想温度で、SAT＝to＋(a×I)/αo で近似される（to：外気温度、a：日射吸収率、I：日射強度、αo：室外側表面熱伝達率）。冷房負荷計算における壁体・屋根の貫流熱量算出に用いる。相当外気温度SATは、外気温度に日射による表面温度上昇分（日射吸収率×日射量÷屋外側熱伝達率）を加えた仮想的な外気温度である。これを用いると日射と貫流をひとつの温度差にまとめて計算できる。表面の色（日射吸収率）が濃いほど、また屋外側熱伝達率が小さいほどSATは高くなる。\n\n【図解】相当外気温度を決める要素\n　要素｜記号｜影響\n　日射吸収率｜a｜濃色ほど大きくSATが上がる\n　日射量｜I｜方位と時刻により変化\n　屋外側熱伝達率｜αo｜大きいほど温度上昇は小さい\n　⇒ SAT＝外気温度＋日射による表面温度上昇分\n　⚠ 屋根や西面壁など日射を強く受ける部位ほど外気温との差が大きくなる。',
