    explanation: '容積比熱（体積比熱）は、材料の単位体積を単位温度上昇させるのに必要な熱量を表す量で、単位はkJ/(m³·K)である。質量比熱[kJ/(kg·K)]に材料密度[kg/m³]を乗じることで求められ、建物の蓄熱性能（熱容量）を評価する際に用いられる。容積比熱は単位体積の材料を1K上昇させるのに必要な熱量で、単位はkJ/(m³·K)である。質量比熱[kJ/(kg·K)]に密度[kg/m³]を乗じて求める。水が約4200、コンクリートが約2000、木材が約600kJ/(m³·K)程度であり、建物の蓄熱性能を比較する際にはこの容積比熱を用いる。\n\n【図解】材料の容積比熱\n　材料｜容積比熱の目安｜蓄熱性\n　水｜約4200 kJ/(m³·K)｜非常に大きい\n　コンクリート｜約2000 kJ/(m³·K)｜大きい\n　木材｜約600 kJ/(m³·K)｜小さい\n　⇒ 容積比熱＝質量比熱×密度で、蓄熱量の比較に用いる\n　⚠ 質量比熱だけで比較しない。木材は質量比熱が大きくても密度が小さく蓄熱量は小さい。',
