    correctKey: 'C',
    explanation: '計画換気による熱損失を低減するには、必要な換気量を確保しつつ排気の保有熱（顕熱・潜熱）を給気側に回収する全熱交換器付き換気設備の採用が有効である。温度交換効率60〜80%程度の全熱交換器を用いることで、換気による熱負荷を大きく低減できる。必要換気量は室内空気質の確保のために定められているため削減できず、換気に伴う熱損失の低減は排気からの熱回収によるのが最も有効である。全熱交換器を用いれば温度と湿度の両方を回収でき、外気負荷を6〜7割低減できる。あわせて気密性を高め、計画外の漏気を減らすことも効果がある。\n\n【図解】換気に伴う熱損失の低減策\n　対策｜換気量｜熱損失\n　換気量を減らす｜減る｜減るが空気質が悪化する\n　熱交換換気を導入｜変わらない｜大幅に低減できる\n　気密性を高める｜漏気が減る｜計画外の損失を低減\n　⇒ 必要換気量は確保したまま熱だけを回収するのが基本\n　⚠ 空気質確保のための換気量を削って省エネを図らない。優先順位を誤らない。',
