    explanation: 'コールドドラフトは、断熱性能の低い窓等の低温表面に接した室内空気が冷やされて密度が増し、下降気流となって床面付近に流れ込む現象である。窓際の局所的な不快感の原因となり、対策として複層ガラス・Low-Eガラスの採用による窓の断熱性能向上や、ペリメーター暖房（窓下ヒーター等）の設置が有効である。コールドドラフトは、断熱性能の低い窓面で冷やされた空気が密度差により下降し、足元へ流れ込んで不快感を生じる現象である。室温が適正でも生じるため、対策は窓の断熱性能向上、窓下への放熱器（ペリメーターヒーター）設置、窓面に沿った吹出しによるエアバリアの形成となる。\n\n【図解】コールドドラフトの対策\n　対策｜作用｜備考\n　窓の断熱性能を上げる｜表面温度を高める｜根本的な対策\n　窓下に放熱器を置く｜下降流を上昇流で相殺｜従来からの手法\n　窓面に沿って吹き出す｜エアバリアを形成｜大きな窓面に有効\n　⇒ 冷えた面に沿う下降流が足元の不快感を生む\n　⚠ 室温を上げても解決しない。原因は空気温度ではなく窓面の表面温度である。',
