    correctKey: 'C',
    explanation: '開放式（蒸発式）冷却塔は冷却水を直接大気中に散布し蒸発潜熱により冷却する方式で、構造が比較的簡易で安価だが冷却水が大気に触れるため水質管理（スケール・レジオネラ対策等）が重要となる。密閉式冷却塔は冷却水を熱交換コイル内に密閉し、コイル外側に散布水を掛けて冷却する方式で、冷却水系統の水質を清浄に保ちやすい利点がある一方、構造が複雑で設備費・設置スペースは開放式より大きくなる傾向がある。\n\n【図解】冷却塔の型式比較\n　項目｜開放式冷却塔｜密閉式冷却塔\n　冷却水の汚れ｜大気に接触し汚れやすい｜熱交換器内で清浄を保てる\n　大きさと価格｜小さく安価｜大きく高価\n　効率｜高い｜やや低い\n　⇒ 水質を重視するなら密閉式、効率と経済性なら開放式\n　⚠ 密閉式でも散布水系統の水質管理は必要。レジオネラ対策が不要になるわけではない。',
